//  CATEGORY: 인터넷 용어 / 网络用语 (Internet Slang)
// =====================================================================

export interface Slang {
  [k: string]: unknown;
  id: string;
  expression: string;
  meaning: string;
  usage: string;
  hotLevel: 1 | 2 | 3;
  mood: string;
  formalWarning: boolean;
  formalAlternative?: string;
  example: string;
  exampleZh: string;
}

